import { defineNuxtPlugin, tryUseNuxtApp } from '#imports'
// Virtual module generated by this module's own `setup()` (see `addTemplate` in `module.ts`) -
// only resolvable once consumed inside a real Nuxt app build, hence the `eslint-disable`/
// `ts-ignore` pair instead of `@ts-expect-error` (which would itself be flagged as unused once
// the ambient declaration is generated).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { staticItems, sources } from '#menus/sources'
import { getAppMenuStore, pushMenuItems, resetMenus, setAppMenuStoreResolver } from '../utils/state'
import type { MenuItem, MenuSource } from '../../../types'

type MenuSourceEntry = { menu: string, source: MenuSource }

/**
 * Populates this app instance's menu state, consumed by `useMenu`: first with every item registered
 * at build time (`extendMenu`), then by running every registered module's dynamic `runtime/menus.ts`
 * source once per app instance (server: once per request, client: once on hydration). The state is
 * held per app instance, so concurrent server requests never share or clobber each other's menus.
 */
export default defineNuxtPlugin({
  name: 'frigear-nu:menus',
  async setup(nuxtApp) {
    const store = getAppMenuStore(nuxtApp)
    // Lets `extendMenuItem`, called from a source, find this app's store through the Nuxt context.
    setAppMenuStoreResolver(() => {
      const app = tryUseNuxtApp()
      return app ? getAppMenuStore(app) : undefined
    })
    resetMenus(store)

    for (const [menu, groups] of Object.entries(staticItems as Record<string, Record<string, MenuItem[]>>)) {
      for (const [group, items] of Object.entries(groups)) {
        if (items.length > 0) pushMenuItems(store, menu, group, items)
      }
    }

    for (const { menu, source } of sources as MenuSourceEntry[]) {
      const items: Parameters<MenuSource>[0] = []
      // The Nuxt context (used by `extendMenuItem`) is only guaranteed for the synchronous part of
      // a source, i.e. before its first `await`.
      await nuxtApp.runWithContext(() => source(items))
      if (items.length > 0) pushMenuItems(store, menu, '', items)
    }
  },
})
